def bgm_play(bgm, track = nil)
  old_pos = @bgm_position
  @bgm_position = 0
  bgm_play_internal(bgm, 0, track)
  @bgm_position = old_pos
end

def bgm_play_internal2(name, volume, pitch, position, track = nil) # :nodoc:
  vol = volume
  vol *= $PokemonSystem.bgmvolume / 100.0
  vol = vol.to_i
  begin
    Audio.bgm_play(name, vol, pitch, position, track)
  rescue ArgumentError
    Audio.bgm_play(name, vol, pitch, 0, track)
  end
end

def bgm_play_internal(bgm, position, track = nil) # :nodoc:
  if !track || track == 0
    @bgm_position = position if !@bgm_paused
    @playing_bgm = bgm&.clone
  end
  if bgm && bgm.name != ""
    if !@defaultBGM && FileTest.audio_exist?("Audio/BGM/" + bgm.name)
      bgm_play_internal2("Audio/BGM/" + bgm.name, bgm.volume, bgm.pitch, @bgm_position, track)
    end
  else
    if !track || track == 0
      @bgm_position = position if !@bgm_paused
      @playing_bgm = nil
    end
    Audio.bgm_stop(track) if !@defaultBGM
  end
  if @defaultBGM
    bgm_play_internal2("Audio/BGM/" + @defaultBGM.name,
                       @defaultBGM.volume, @defaultBGM.pitch, @bgm_position, track)
  end
  Graphics.frame_reset
end

def bgm_pause(fadetime = 0.0) # :nodoc:
  pos = Audio.bgm_pos rescue 0
  self.bgm_fade(fadetime) if fadetime > 0.0
  @bgm_position = pos
  @bgm_paused   = true
end

def bgm_unpause  # :nodoc:
  @bgm_position = 0
  @bgm_paused   = false
end

def bgm_resume(bgm) # :nodoc:
  if @bgm_paused
    self.bgm_play_internal(bgm, @bgm_position)
    @bgm_position = 0
    @bgm_paused   = false
  end
end

def pbSwapBattlerSprites(idxA, idxB)
  @sprites["pokemon_#{idxA}"], @sprites["pokemon_#{idxB}"] = @sprites["pokemon_#{idxB}"], @sprites["pokemon_#{idxA}"]
  @sprites["shadow_#{idxA}"], @sprites["shadow_#{idxB}"] = @sprites["shadow_#{idxB}"], @sprites["shadow_#{idxA}"]
  @lastCmd[idxA], @lastCmd[idxB] = @lastCmd[idxB], @lastCmd[idxA]
  @lastMove[idxA], @lastMove[idxB] = @lastMove[idxB], @lastMove[idxA]
  [idxA, idxB].each do |i|
    @sprites["pokemon_#{i}"].index = i
    @sprites["pokemon_#{i}"].pbSetPosition
    @sprites["shadow_#{i}"].index = i
    @sprites["shadow_#{i}"].pbSetPosition
    @sprites["dataBox_#{i}"].battler = @battle.battlers[i]
  end
  pbRefresh
end

def pbShowPartyLineup(side, fullAnim = false)
  @animations.push(
    Animation::LineupAppear.new(@sprites, @viewport, side,
                                @battle.pbParty(side), @battle.pbPartyStarts(side),
                                fullAnim)
  )
  return if fullAnim
  while inPartyAnimation?
    pbUpdate
  end
end
